create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_MART_LIDL_DIGITAL.T_AGG_RCPT_COUPON_PROMO_DISCOUNT_LDPL_DAY_1 cluster by (client_id, dwh_cal_dt)(
	ASPECT_ID NUMBER(38,0) NOT NULL COMMENT 'Gesellschaftsform (1 = Betriebs- 2 = Vertriebsgesellschaft)',
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier for client',
	GEO_AREA_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Identifier for geographical country_1',
	DWH_CAL_DT DATE NOT NULL COMMENT 'Data date',
	CY_MONTH NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Calendar_1 Year+Month in form YYYYMM',
	CY_MONTH_PREV_1M NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'The calendar_1 month 1 month ago as a number in the form YYYYMM. Eg. 201901.    [Month Identifier]',
	CY_MONTH_PREV_1Y NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'The calendar_1 month 1 year ago as a number in the form YYYYMM. Eg. 201802.    [Month Identifier]',
	CY_WEEK NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'The week (containing the day) as a number in the form YYYYWW. YYYY is the year of the week and WW is the number of the week within the calendar_1 year. Week 1 is the first week in the calendar_1 year containing at least 4 days.    [Week Identifier]',
	CY_WEEK_PREV_1W NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'The week 1 week (= 7 days) ago as a number in the form YYYYWW. Eg. 202052.    [Week Identifier]',
	CY_WEEK_PREV_1Y NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'The week 1 year (= 364 days = 52 weeks) ago as a number in the form YYYYWW. Eg. 202001.    [Week Identifier]',
	BUSYEAR_QTR NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Identifier of the quarter of the busines year',
	WK_RF_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of recency-frequency segments from rfm model',
	WK_M_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of monetary segments from rfm model',
	WK_ST_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of STRATEGIC segments from rfm model',
	WK_FR_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of FREQUENCY segments from rfm model',
	WK_RE_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of RECENCY segments from rfm model',
	WK_MO_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of NEW monetary segments from rfm model',
	MTH_RF_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of recency-frequency segments from rfm model',
	MTH_M_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of monetary segments from rfm model',
	MTH_ST_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of STRATEGIC segments from rfm model',
	MTH_FR_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of FREQUENCY segments from rfm model',
	MTH_RE_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of RECENCY segments from rfm model',
	MTH_MO_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of NEW monetary segments from rfm model',
	BUSYEAR_QTR_RF_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of recency-frequency segments from rfm model',
	BUSYEAR_QTR_M_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of monetary segments from rfm model',
	LOC_SID NUMBER(38,0) NOT NULL COMMENT 'Store ID',
	COUPON_PROMO_SID NUMBER(38,0) NOT NULL COMMENT 'Unique identifier of the coupon_promotion (surrogate key in t_coupon_promotion_hist. Default value for Sonstige -2)',
	MOVE_TO_STORE_ID NUMBER(38,0) NOT NULL COMMENT 'Filialnummer nach letztem Filialumzug',
	WH_ID NUMBER(38,0) NOT NULL COMMENT 'Warehouse ID',
	LIDLPLUS_CUST_FG VARCHAR(1) NOT NULL COMMENT 'Lidl Plus Customer Flag',
	CUSTOMER_SID NUMBER(38,0) NOT NULL COMMENT 'Customer identifier',
	CURRENCY_ISO_CD VARCHAR(3) NOT NULL COMMENT 'ISO code for the currency of the client.',
	CURR_TOT_ID NUMBER(38,0) NOT NULL COMMENT 'Fixe Werte fur EUR=0 GBP=40 sonst Client_Id',
	FEATURE_ID NUMBER(38,0) NOT NULL COMMENT 'Categorization of LidlPlus Coupons and their Promotion : p_lew_core.t_ref_coupon_promotion_type.coupon_promo_type_sid based on SCRM NN.dim_promotion.promotion_type_description',
	COUPON_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'Categorization of LidlPlus Coupons : p_lew_core.t_ref_orig_coupon_type.orig_coupon_type_sid based on SCRM L1.promotionhst.category',
	DISCOUNT_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'Categorization of LidlPlus Coupons : p_lew_core.t_ref_orig_discount_type.orig_discount_type_sid based on SCRM L1.promotionhst.discount_type',
	REGISTER_ID NUMBER(38,0) NOT NULL COMMENT 'Kassennummer; WAWI-DWH: t_ejr_receiptheader.pos_terminal_id',
	RECEIPT_ID NUMBER(38,0) NOT NULL COMMENT 'Bon-Nummer; WAWI-DWH: t_ejr_receiptheader.orig_receipt_nr_ejr',
	ITEM_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Item_1 surrogate ID (uniquely across all countries/clients)',
	EAN_BARCODE VARCHAR(100) COMMENT 'European Article Number',
	PCWO_REASON_ID NUMBER(38,0) DEFAULT 0 COMMENT 'Unique ID of the write-off or Price change reason. Country_1-specific write-off reasons have ID>100.',
	COUPON_REASON_NR NUMBER(38,0) DEFAULT 0 COMMENT 'Identifier of the booking reason in SCRM',
	DISCOUNT_SID NUMBER(38,0) COMMENT 'Rabattgrund - Code; WAWI-DWH: t_ejr_receiptline.discount_id',
	DISCOUNT_VAL NUMBER(25,10) NOT NULL COMMENT 'Discount value',
	WRITEOFF_VAL NUMBER(25,10) DEFAULT 0 COMMENT 'Writeoff net value',
	RECEIPT_TOTAL_NET_VAL_UNIQ NUMBER(38,25) NOT NULL COMMENT 'Total net value of the whole Receipt as Decimal(18,5), concatenated with 000 and 17 digits of a MD5 on receipt Primary key. Used for Sum(Distinct receipt_total_net_val_uniq)',
	RECEIPT_ITEM_DISCOUNT_PIECE_WEIGHT_QTY_UNIQ NUMBER(38,25) NOT NULL DEFAULT 0 COMMENT 'Unit_1 Sold - Sales_1 (in units/kg) per item_sid as Decimal(18,5), concatenated with 000 and 17 digits of a MD5 on receipt Primary key + item_sid. Used for Sum Distinct',
	RECEIPT_TOTAL_NET_VAL_ITEM_UNIQ NUMBER(38,25) COMMENT 'Total net value per article levelcasted as Decimal(18,5), concatenated with 000 and 17 digits of a MD5 on receipt Primary key. Used for Sum(Distinct receipt_total_net_val_item_uniq)',
	REDEMPTIONS_CNT_UNIQ NUMBER(38,0) COMMENT 'Unique redemtion hash per client_id, dwh_cal_dt, loc_sid, receipt_id, register_id, p_lew_core.t_scrm_receiptline.src_coupon_promo_nr',
	COUPON_CNT_UNIQ NUMBER(38,0) COMMENT 'Unique coupon hash per client_id, p_lew_core.t_scrm_receiptline.src_coupon_promo_nr',
	COUPON_SOURCE_ID NUMBER(38,0) COMMENT 'Coupon source: 0 - core receipt + core SCRM receipt (p_lew_core_ac.v_scrm_receiptline_1), 1 - only core receipt',
	LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Load identifier',
	DWH_INSERTED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row insert time',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row update time',
	DWH_ATTR_UPDATED TIMESTAMP_NTZ(9) COMMENT 'Row attributes update time',
	constraint PK_AGG_RCPT_COUPON_PROMO_DISCOUNT_LDPL_DAY primary key (ASPECT_ID, CLIENT_ID, DWH_CAL_DT, LOC_SID, CURRENCY_ISO_CD, FEATURE_ID, COUPON_TYPE_ID, DISCOUNT_TYPE_ID, REGISTER_ID, RECEIPT_ID, ITEM_SID)
)COMMENT='Lidlplus : Receipt header coupon promotion discount aggregated to day level'
;
